PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS clubs(club_id INTEGER PRIMARY KEY,club_key TEXT UNIQUE,name TEXT,country TEXT);
CREATE TABLE IF NOT EXISTS periods(period_id TEXT PRIMARY KEY,season TEXT,half TEXT,start_date TEXT,end_exclusive TEXT,timezone TEXT);
CREATE TABLE IF NOT EXISTS competitions(competition_id INTEGER PRIMARY KEY,name TEXT,category TEXT,country TEXT);
CREATE TABLE IF NOT EXISTS acquisition_sources(source_id TEXT PRIMARY KEY,club_id INTEGER,organization TEXT,url TEXT,policy_json TEXT);
CREATE TABLE IF NOT EXISTS raw_artifacts(artifact_id TEXT PRIMARY KEY,source_id TEXT,path TEXT,sha256 TEXT,size INTEGER,kind TEXT,acquired_at TEXT,observed_at TEXT,effective_period TEXT);
CREATE TABLE IF NOT EXISTS matches(match_id INTEGER PRIMARY KEY,home_id INTEGER,away_id INTEGER,kickoff TEXT,local_date TEXT,period_id TEXT REFERENCES periods,competition_id INTEGER REFERENCES competitions,result TEXT,artifact_id TEXT REFERENCES raw_artifacts,observed_at TEXT,source_competition_id INTEGER);
CREATE TABLE IF NOT EXISTS players(player_id INTEGER PRIMARY KEY,display_name TEXT,identity_status TEXT DEFAULT 'source_observed_not_independently_verified');
CREATE TABLE IF NOT EXISTS match_processing(club_id INTEGER,match_id INTEGER,artifact_id TEXT,acquisition_status TEXT,processing_status TEXT,reason TEXT,observed_at TEXT,PRIMARY KEY(club_id,match_id));
CREATE TABLE IF NOT EXISTS squad_observations(club_id INTEGER,match_id INTEGER REFERENCES matches,player_id INTEGER REFERENCES players,role TEXT,shirt_number TEXT,source_name TEXT,json_path TEXT,artifact_id TEXT REFERENCES raw_artifacts,observed_at TEXT,PRIMARY KEY(club_id,match_id,player_id));
CREATE TABLE IF NOT EXISTS player_match_minutes(club_id INTEGER,match_id INTEGER REFERENCES matches,player_id INTEGER REFERENCES players,minutes REAL,minutes_status TEXT,played INTEGER,artifact_id TEXT,PRIMARY KEY(club_id,match_id,player_id));
CREATE TABLE IF NOT EXISTS identity_issues(issue_id TEXT PRIMARY KEY,club_id INTEGER,match_id INTEGER,player_id INTEGER,kind TEXT,detail TEXT,observed_at TEXT);
CREATE TABLE IF NOT EXISTS official_snapshots(snapshot_id TEXT PRIMARY KEY,source_id TEXT REFERENCES acquisition_sources,club_id INTEGER,period_id TEXT REFERENCES periods,artifact_id TEXT REFERENCES raw_artifacts,captured_at TEXT,effective_from TEXT,effective_to TEXT,acquisition_status TEXT,parse_status TEXT,content_review_status TEXT);
CREATE TABLE IF NOT EXISTS official_membership(snapshot_id TEXT REFERENCES official_snapshots,official_player_id TEXT,source_name TEXT,date_of_birth TEXT,shirt_number TEXT,fotmob_player_id INTEGER,provenance TEXT,PRIMARY KEY(snapshot_id,official_player_id));
CREATE TABLE IF NOT EXISTS provider_identities(mapping_id TEXT PRIMARY KEY,source_id TEXT,official_player_id TEXT,fotmob_player_id INTEGER,full_name TEXT,date_of_birth TEXT,club_id INTEGER,season TEXT,confidence TEXT,evidence_artifact_id TEXT,review_status TEXT);
CREATE TABLE IF NOT EXISTS acquisition_attempts(attempt_id INTEGER PRIMARY KEY,source_id TEXT,status TEXT,http_status INTEGER,reason TEXT,artifact_id TEXT,attempted_at TEXT);
CREATE TABLE IF NOT EXISTS manual_actions(source_id TEXT PRIMARY KEY,status TEXT,url TEXT,last_step TEXT,next_action TEXT,login_required TEXT,season_selection TEXT,export_button TEXT,recommended_format TEXT,destination TEXT);
CREATE TABLE IF NOT EXISTS update_jobs(job_key TEXT PRIMARY KEY,kind TEXT,url TEXT,status TEXT,last_checked TEXT,reason TEXT);
CREATE VIEW IF NOT EXISTS historical_membership AS SELECT o.club_id,m.period_id,o.player_id,MIN(m.local_date) first_observed,MAX(m.local_date) last_observed,COUNT(*) match_evidence_count FROM squad_observations o JOIN matches m USING(match_id) GROUP BY o.club_id,m.period_id,o.player_id;
CREATE VIEW IF NOT EXISTS verified_baseline_membership AS SELECT s.club_id,s.period_id,b.fotmob_player_id player_id,s.snapshot_id FROM official_membership b JOIN official_snapshots s USING(snapshot_id) WHERE s.parse_status='VERIFIED' AND b.fotmob_player_id IS NOT NULL;
CREATE VIEW IF NOT EXISTS combined_membership AS SELECT club_id,period_id,player_id,MAX(baseline) listed_in_baseline,MAX(observed) observed_in_matchday FROM (SELECT club_id,period_id,player_id,0 baseline,1 observed FROM historical_membership UNION ALL SELECT club_id,period_id,player_id,1 baseline,0 observed FROM verified_baseline_membership) GROUP BY club_id,period_id,player_id;

CREATE TABLE IF NOT EXISTS official_membership_details(snapshot_id TEXT,local_member_id TEXT,ordinal INTEGER,position TEXT,nationality TEXT,country_code TEXT,official_source_player_id TEXT,line_start INTEGER,line_end INTEGER,PRIMARY KEY(snapshot_id,local_member_id),FOREIGN KEY(snapshot_id,local_member_id) REFERENCES official_membership(snapshot_id,official_player_id));
CREATE TABLE IF NOT EXISTS official_identity_candidates(snapshot_id TEXT,local_member_id TEXT,fotmob_player_id INTEGER,method TEXT,review_status TEXT,evidence_json TEXT,PRIMARY KEY(snapshot_id,local_member_id,fotmob_player_id));
